1	// End-to-end regression coverage for the homepage draft-save race:
2	// after clicking save, the user keeps typing while waiting for the response.
3	// Those later keystrokes must neither be lost when the save succeeds nor be
4	// falsely reported as saved. Scenarios exercise the real form, status text,
5	// draft list, a second save and reopening the draft — never just the API.
6	//
7	// Run: node test/run.mjs   (CHROME_BIN can override the browser executable)
8	import assert from 'node:assert/strict';
9	import { Browser } from './cdp.mjs';
10	import { TestServer } from './server.mjs';
11	import * as ui from './ui.mjs';
12	
13	const tests = [];
14	function test(name, fn) { tests.push({ name, fn }); }
15	
16	async function seed(server, fields) {
17	  const res = await server.api('/api/articles', {
18	    method: 'POST',
19	    body: JSON.stringify({ summary: '', ...fields }),
20	  });
21	  assert.equal(res.status, 201, `seed failed: ${res.status}`);
22	  return (await res.json()).article;
23	}
24	
25	// Seeds happen out-of-band (as if saved in another tab), so the page must
26	// reload its list before the user can click the new draft's 编辑 button.
27	async function seedAndReload(server, page, fields) {
28	  const article = await seed(server, fields);
29	  await ui.reload(page);
30	  return article;
31	}
32	
33	async function freshContext(browser) {
34	  const server = await TestServer.start();
35	  const page = await ui.open(browser, server.url);
36	  return { server, page };
37	}
38	
39	async function closeContext({ server, page }, browser) {
40	  ui.assertNoPageErrors(page);
41	  await browser.closePage(page);
42	  await server.stop();
43	}
44	
45	// ---------------------------------------------------------------------------
46	// 1. Editing an existing draft: save, keep typing during the wait, save again.
47	// ---------------------------------------------------------------------------
48	test('编辑态保存等待期间继续输入：内容保留、只提示未保存字段、再次保存生效、重开一致', async (browser) => {
49	  const ctx = await freshContext(browser);
50	  const { server, page } = ctx;
51	  try {
52	    const a = await seedAndReload(server, page, {
53	      title: '原标题',
54	      summary: '原摘要',
55	      body: '原正文第一段\n\n原正文第二段',
56	    });
57	
58	    // 用户实际操作：打开已有草稿（正文以单篇接口返回为准）。
59	    await ui.clickEdit(page, '原标题');
60	    await ui.waitLoadedDraft(page);
61	    let s = await ui.state(page);
62	    assert.equal(s.saveBtnText, '保存修改');
63	    assert.deepEqual(s.form, { title: '原标题', summary: '原摘要', body: '原正文第一段\n\n原正文第二段' });
64	    assert.equal(s.bannerId, a.id);
65	
66	    // 提交标题、摘要、正文。
67	    await ui.fill(page, {
68	      title: '  修改后的标题  ',
69	      summary: '实际提交的摘要 <b>x</b>',
70	      body: '实际提交的正文第一段\n\n实际提交的正文第二段',
71	    });
72	    await ui.gateOn(page);
73	    await ui.clickSave(page);
74	    await ui.waitSavingPending(page, 1);
75	
