1	// Page-level helpers for the draft-save regression tests.
2	//
3	// The core of every scenario is the race the product must survive: the user
4	// clicks save, then keeps typing while the request is in flight. Real network
5	// round-trips are too fast to type against reliably, so before the page's own
6	// scripts run we install a tiny gate on window.fetch: a save call (POST/PUT to
7	// /api/articles) can be held inside the browser until the test releases it.
8	// Everything else (list reads, article reads) passes through untouched. The
9	// product itself has no test-only code paths.
10	const INIT_SOURCE = `(function () {
11	  if (window.__qtest) return;
12	  var gate = { enabled: false, hits: 0, pending: [] };
13	  var origFetch = window.fetch.bind(window);
14	  function isSaveCall(input, init) {
15	    var url = typeof input === 'string' ? input : ((input && input.url) || '');
16	    var path = url.split('?')[0];
17	    var method = ((init && init.method) || 'GET').toUpperCase();
18	    if (method !== 'POST' && method !== 'PUT') return false;
19	    return path === '/api/articles' || /^\\/api\\/articles\\//.test(path);
20	  }
21	  window.fetch = function (input, init) {
22	    if (gate.enabled && isSaveCall(input, init)) {
23	      gate.hits++;
24	      return new Promise(function (resolve) {
25	        gate.pending.push(function () { resolve(origFetch(input, init)); });
26	      });
27	    }
28	    return origFetch(input, init);
29	  };
30	  function byId(id) { return document.getElementById(id); }
31	  // Go through the prototype value setter so React-style change detection and
32	  // the page's input listeners see a genuine user edit.
33	  function setValue(id, value) {
34	    var node = byId(id);
35	    var proto = node.tagName === 'TEXTAREA'
36	      ? window.HTMLTextAreaElement.prototype
37	      : window.HTMLInputElement.prototype;
38	    Object.getOwnPropertyDescriptor(proto, 'value').set.call(node, value);
39	    node.dispatchEvent(new Event('input', { bubbles: true }));
40	    node.dispatchEvent(new Event('change', { bubbles: true }));
41	  }
42	  window.__qtest = {
43	    set: function (id, value) { setValue(id, value); },
44	    click: function (id) { byId(id).click(); },
45	    clickEdit: function (title) {
46	      var cards = document.querySelectorAll('#article-list article.draft');
47	      for (var i = 0; i < cards.length; i++) {
48	        var h3 = cards[i].querySelector('h3');
49	        var text = h3 && h3.firstChild ? h3.firstChild.nodeValue : '';
50	        if (text === title) { cards[i].querySelector('button').click(); return true; }
51	      }
52	      return false;
53	    },
54	    gateOn: function () { gate.enabled = true; gate.hits = 0; },
55	    gateOff: function () { gate.enabled = false; },
56	    release: function () {
57	      var pending = gate.pending;
58	      gate.pending = [];
59	      pending.forEach(function (run) { run(); });
60	      return pending.length;
61	    },
62	    gateState: function () {
63	      return { enabled: gate.enabled, hits: gate.hits, pending: gate.pending.length };
64	    }
65	  };
66	  window.__snap = function () {
67	    function v(id) { return document.getElementById(id).value; }
68	    var status = document.getElementById('status');
69	    var banner = document.getElementById('edit-banner');
70	    var cards = Array.prototype.map.call(
71	      document.querySelectorAll('#article-list article.draft'),
72	      function (card) {
73	        var h3 = card.querySelector('h3');
74	        var sum = card.querySelector('.summary');
75	        var btn = card.querySelector('.actions button');
76	        return {
77	          title: h3 && h3.firstChild ? h3.firstChild.nodeValue : '',
78	          summary: sum ? sum.textContent : null,
79	          editing: !!card.querySelector('.editing-tag'),
80	          editBtnText: btn ? btn.textContent : '',
81	          editBtnDisabled: btn ? btn.disabled : null
82	        };
83	      });
84	    var code = banner.querySelector('code');
85	    var meta = banner.querySelector('.meta');
86	    return {
87	      form: { title: v('title'), summary: v('summary'), body: v('body') },
88	      saveBtnText: document.getElementById('save-btn').textContent,
89	      saveDisabled: document.getElementById('save-btn').disabled,
90	      cancelHidden: document.getElementById('cancel-btn').hidden,
91	      formEditing: document.getElementById('draft-form').classList.contains('editing'),
92	      bannerHidden: banner.hidden,
93	      bannerTitle: code ? code.textContent : null,
94	      bannerId: meta ? (meta.textContent.split('标识：')[1] || '') : '',
95	      statusText: status.textContent,
96	      statusKind: (status.className.match(/\\b(ok|err|warn)\\b/) || [])[1] || '',
97	      conflictHidden: document.getElementById('conflict-box').hidden,
98	      cards: cards,
99	      listCount: cards.length,
100	      emptyTip: document.getElementById('empty-tip').textContent
101	    };
102	  };
103	})();`;
104	
105	export async function open(browser, baseUrl) {
106	  const page = await browser.newPage();
107	  await page.enable();
108	  await page.addInitScript(INIT_SOURCE);
109	  await page.goto(baseUrl);
110	  // Initial list fetch has settled.
111	  await page.waitFor(
112	    'function(){return !document.getElementById("empty-tip").textContent.includes("加载中");}',
113	    { label: 'initial draft list settled' });
114	  return page;
115	}
116	
117	export async function reload(page) {
118	  await page.reload();
119	  await page.waitFor(
120	    'function(){return !document.getElementById("empty-tip").textContent.includes("加载中");}',
121	    { label: 'draft list settled after reload' });
122	}
123	
124	export async function fill(page, fields) {
125	  for (const [id, value] of Object.entries(fields)) {
126	    await page.eval(`__qtest.set(${JSON.stringify(id)}, ${JSON.stringify(value)})`);
127	  }
128	}
129	
130	export async function clickSave(page) {
131	  await page.eval(`__qtest.click('save-btn')`);
132	}
133	
134	export async function clickCancel(page) {
135	  await page.eval(`__qtest.click('cancel-btn')`);
136	}
137	
138	export async function clickEdit(page, title) {
139	  const clicked = await page.eval(`__qtest.clickEdit(${JSON.stringify(title)})`);
140	  if (!clicked) throw new Error(`no draft card titled ${JSON.stringify(title)} to edit`);
141	}
142	
143	export async function gateOn(page) { await page.eval(`__qtest.gateOn()`); }
144	export async function gateOff(page) { await page.eval(`__qtest.gateOff()`); }
145	export async function releaseSaves(page) { return page.eval(`__qtest.release()`); }
146	
147	// The save request is parked in the browser and the UI shows its in-flight state.
148	export async function waitSavingPending(page, count = 1) {
149	  await page.waitFor(
150	    `function(){var g=__qtest.gateState();return g.pending===${count} && __snap().saveDisabled && __snap().saveBtnText==='保存中…';}`,
151	    { timeout: 5000, label: `save request #${count} parked while button shows 保存中…` });
152	}
153	
154	export function state(page) {
155	  return page.eval(`__snap()`);
156	}
157	
158	export async function waitForStatus(page, text, kind) {
159	  const kindCheck = kind ? ` && s.statusKind===${JSON.stringify(kind)}` : '';
160	  await page.waitFor(
161	    `function(){var s=__snap();return s.statusText.includes(${JSON.stringify(text)})${kindCheck};}`,
162	    { timeout: 8000, label: `status containing ${JSON.stringify(text)}${kind ? ` (${kind})` : ''}` });
163	}
164	
165	export async function waitLoadedDraft(page) {
166	  await waitForStatus(page, '已载入该草稿当前保存的内容');
167	  await page.waitFor('function(){return !__snap().bannerHidden && __snap().saveBtnText==="保存修改";}',
168	    { label: 'editing banner and 保存修改 button' });
169	}
170	
171	export async function getConflict(page) {
172	  return page.eval(`(function () {
173	    var box = document.getElementById('conflict-box');
174	    function column(selector) {
175	      var ver = box.querySelector(selector);
176	      if (!ver) return null;
177	      var dds = ver.querySelectorAll('dd');
178	      function val(dd) { return dd.classList.contains('empty-field') ? '' : dd.textContent; }
179	      return {
180	        heading: ver.querySelector('h4').textContent,
181	        title: val(dds[0]),
182	        summary: val(dds[1]),
183	        body: val(dds[2])
184	      };
185	    }
186	    return {
187	      hidden: box.hidden,
188	      mine: column('.ver.mine'),
189	      saved: column('.ver.saved')
190	    };
191	  })()`);
