// 推进到“冲突对照已显示、且对照之后服务端又保存了一版”的状态。
async function reachStaleConflict(server, page, seedFields, myInput, v1Fields, v2Fields) {
  const a = await seedAndReload(server, page, seedFields);
  await ui.clickEdit(page, seedFields.title);
  await ui.waitLoadedDraft(page);
  const v1 = await putArticle(server, a, v1Fields, 1);   // 另一页保存 → version 2
  await ui.fill(page, myInput);
  await ui.clickSave(page);
  await ui.waitForStatus(page, '409', 'err');
  const v2 = await putArticle(server, v1, v2Fields, 2);  // 对照之后另一页又保存 → version 3
  return { a, v1, v2 };
}

async function putArticle(server, article, fields, version) {
  const res = await server.api(`/api/articles/${article.id}`, {
    method: 'PUT',
    body: JSON.stringify({ ...fields, version }),
  });
  assert.equal(res.status, 200, `PUT failed: ${res.status}`);
  return (await res.json()).article;
}
```

